import type { CognitiveDemand, DepthQuestion, LessonDepthPack, QuestionEvidence } from "./curriculum-depth-types.ts";

function evidence(objectiveId: string, demand: CognitiveDemand, representation: QuestionEvidence["representation"], misconception: string): QuestionEvidence {
  return { objectiveId, demand, representation, difficulty: 2, misconception, variantFamily: `${objectiveId}-variants` };
}

function choice(n: number, objective: string, demand: CognitiveDemand, prompt: string, choices: string[], answer: string, hint: string, explanation: string, misconception: string): DepthQuestion {
  return { id: `d1-q${n}`, prompt, choices, answer, hint, explanation, interaction: "four-choice", evidence: evidence(objective, demand, demand === "procedure" ? "symbolic" : "verbal", misconception) };
}

function table(n: number, objective: string, prompt: string, columns: string[], rows: string[][], correctRow: number, hint: string, explanation: string, misconception: string): DepthQuestion {
  const options = rows.map((cells, i) => ({ value: String.fromCharCode(65 + i), cells }));
  return { id: `d1-q${n}`, prompt, choices: options.map((row) => row.value), answer: options[correctRow].value, hint, explanation, interaction: "table-choice", interactionConfig: { kind: "table-choice", columns, rows: options }, evidence: evidence(objective, "representation", "table", misconception) };
}

